do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int;
begin
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Gopuff$q$,$q$private_company$q$),($q$Grubhub$q$,$q$private_company$q$),($q$Marlin9 Holdings (Wynshop)$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$Based upon this assessment, reductions were made to our net operating loss and tax credit carryforwards under these rules for the acquisition of Marlin9 Holdings, Inc.$q$),(2,$q$For example, in April 2025, we acquired Marlin9 Holdings, Inc., which operates as Wynshop, a provider of e-commerce retail solutions for grocers and retailers.$q$),(3,$q$In addition, we may not be able to effectively compete with service offerings from vertically integrated competitors, such as Amazon or Gopuff, which control both the brick-and-mortar retailer and online fulfillment technology.$q$),(4,$q$On April 30, 2025, pursuant to a Stock Purchase Agreement, the Company acquired a 
100
% ownership interest in Marlin9 Holdings, Inc. which operates as Wynshop (“Wynshop”), a provider of e-commerce retail solutions for grocers and retailers.$q$),(5,$q$With respect to Instacart Marketplace, our current and potential competitors include, but are not limited to: (i) existing and well-established online grocery or shopping alternatives, including digital-first platforms, such as Amazon and Thrive Market, (ii) brick-and-mortar retailers that have their own digital and fulfillment offerings, such as Target and Walmart, some of which decide to partner with Instacart to complement their own offerings, (iii) companies that provide e-commerce and fulfillment services for third parties, including retailers, whether online or offline, such as DoorDash, Shipt (acquired by Target), and Uber Eats, (iv) digital-first platforms entering the grocery market by owning inventory, including DashMart (owned by DoorDash), Fresh Direct (owned by Getir), and Gopuff, which may include existing retailers on Instacart, which could eventually eliminate their need to partner with us or limit their use of Instacart Marketplace, (v) companies that provide e-commerce and fulfillment services that focus on discrete categories of products, such as alcohol or prescription delivery, and (vi) companies that offer direct to consumer ingredient or meal offerings, such as Blue Apron (owned by Wonder Group) or Misfits Market, some of which may partner with Instacart to complement their own offerings.$q$),(6,$q$With respect to restaurants offered on Instacart’s Marketplace via our partnership with Uber, there are a number of competitors to such offering available through Instacart including, but not limited to: (i) local on-demand delivery companies such as DoorDash, Uber Eats via Uber’s native applications, and Grubhub (acquired by Wonder), (ii) restaurants that have their own online ordering platform or online ordering systems, and (iii) other businesses that offer online ordering of prepared meals.$q$),(7,$q$enter into and maintain strategic partnerships, including our partnership with Uber to offer their restaurant delivery services on our platform;$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$partners$q$,$q$CART$q$,$q$Uber$q$,$q${7,6}$q$::int[],$q${risk_factors,risk_factors}$q$::text[],null,null,null,null),(2,$q$competes$q$,$q$CART$q$,$q$Amazon$q$,$q${5,3}$q$::int[],$q${risk_factors,risk_factors}$q$::text[],null,null,null,null),(3,$q$competes$q$,$q$CART$q$,$q$DoorDash$q$,$q${6}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(4,$q$competes$q$,$q$CART$q$,$q$Uber Eats$q$,$q${6}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(5,$q$competes$q$,$q$CART$q$,$q$Grubhub$q$,$q${6}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(6,$q$competes$q$,$q$CART$q$,$q$Gopuff$q$,$q${3}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(7,$q$acquires$q$,$q$CART$q$,$q$Marlin9 Holdings (Wynshop)$q$,$q${2,1,4}$q$::int[],$q${risk_factors,risk_factors,notes}$q$::text[],100,$q$exact$q$,$q$source_revenue$q$,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Amazon$q$ then ticker=$q$AMZN$q$ when $q$Uber Eats$q$ then ticker=$q$UBER$q$ when $q$Uber$q$ then ticker=$q$UBER$q$ when $q$DoorDash$q$ then ticker=$q$DASH$q$ when $q$CART$q$ then ticker=$q$CART$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,status,review_status) values ('filings_extraction','batch',$q$CART M6 group 2-4$q$,'claude-sonnet-5-5',283127,3918,0.8468,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; end if; if (select status from public.relationships where id=rid)='staged' then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1579091/000157909126000018/cart-20251231.htm$q$,r.sec[k],t,true,$q$2026-02-26$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
